import React from 'react';
import './Posts.css';


function Posts({id,userPic,name,text,photo}){
    return(
    <div class="Posts.html?id={id}">
    <div class="card g-3">
    <button type="button" class="btn-close" disabled aria-label="Close"></button>
    <post>
    <div class="card-body">
        <img src={userPic} class="card-img-bottom" alt="userPec"></img>
        <h5 class="card-title">{name}</h5>
        <p class="card-text">{text}</p>
    </div>
    <img src={photo} class="card-img" alt="postPic"></img>
    </post>
</div>
</div>);
}
export default Posts;
